code='''def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    from collections import Counter
    bg = Counter(v for row in g for v in row).most_common(1)[0][0]

    def runs(vals):
        out=[]; i=0
        while i < len(vals):
            if vals[i] == bg:
                i += 1; continue
            color=vals[i]; j=i+1
            while j < len(vals) and vals[j] == color:
                j += 1
            out.append((i,j-1,color))
            i=j
        return out

    # Find matching colored bars on opposite borders.
    choices=[]
    for orient in ('horizontal','vertical'):
        if orient == 'horizontal':
            a, b = runs(g[0]), runs(g[-1])
            axis_len, cross_len = w, h
        else:
            a, b = runs([g[r][0] for r in range(h)]), runs([g[r][-1] for r in range(h)])
            axis_len, cross_len = h, w
        for ra in a:
            for rb in b:
                if ra[2] == rb[2]:
                    choices.append((orient, ra, rb))
    if not choices:
        return g
    orient, bar_a, bar_b = choices[0]
    colorbar=bar_a[2]
    markers=[]
    for r in range(h):
        for c in range(w):
            if g[r][c] != bg and g[r][c] != colorbar:
                markers.append((r,c,g[r][c]))
    if not markers:
        return g

    # Select the border bar whose coordinate interval contains the markers.
    def axis_coord(m): return m[1] if orient == 'horizontal' else m[0]
    count_a=sum(bar_a[0] <= axis_coord(m) <= bar_a[1] for m in markers)
    count_b=sum(bar_b[0] <= axis_coord(m) <= bar_b[1] for m in markers)
    if count_b > count_a:
        ref, other = bar_b, bar_a
        ref_side='last'
    else:
        ref, other = bar_a, bar_b
        ref_side='first'

    for r,c,col in markers:
        pos=axis_coord((r,c,col))
        if not (ref[0] <= pos <= ref[1]):
            continue
        offset=pos-ref[0]
        mapped=other[0]+offset
        if mapped <= other[1]:
            # Project the marker's relative position from the opposite bar across the grid.
            if orient == 'horizontal':
                for rr in range(h):
                    if g[rr][mapped] == bg:
                        g[rr][mapped]=col
            else:
                for cc in range(w):
                    if g[mapped][cc] == bg:
                        g[mapped][cc]=col
        # Extend the marker to its associated border bar.
        if orient == 'horizontal':
            step=1 if ref_side == 'last' else -1
            rr=r+step
            while 0 <= rr < h and g[rr][c] == bg:
                g[rr][c]=col
                rr += step
        else:
            step=1 if ref_side == 'last' else -1
            cc=c+step
            while 0 <= cc < w and g[r][cc] == bg:
                g[r][cc]=col
                cc += step
        g[r][c]=4
    return g
